'use strict';

/**
 * Voucher codes. Generated by the server with a CSPRNG, 12 symbols from a 32-symbol alphabet that leaves out the
 * look-alikes (0 O 1 I): 60 bits, so a code cannot be guessed. Stored and looked up NORMALISED (upper case, no spaces or
 * dashes); shown with dashes in groups of four. `normalizeVoucherCode` is the only way input becomes a lookup key.
 */

const crypto = require('crypto');

const VOUCHER_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const VOUCHER_CODE_LENGTH = 12;

function generateVoucherCode() {
  let code = '';
  for (let i = 0; i < VOUCHER_CODE_LENGTH; i += 1) code += VOUCHER_ALPHABET[crypto.randomInt(VOUCHER_ALPHABET.length)]; // randomInt is unbiased
  return code;
}

/** Trim, upper-case, strip spaces and dashes. Anything that is not text becomes the empty string. */
function normalizeVoucherCode(input) {
  if (typeof input !== 'string') return '';
  return input.trim().toUpperCase().replace(/[\s-]+/g, '');
}

function formatVoucherCode(code) {
  const clean = normalizeVoucherCode(code);
  return clean.match(/.{1,4}/g)?.join('-') ?? '';
}

/** Only letters and digits, 8 to 24 of them: anything else cannot be a code, so no lookup is made for it. */
function isPlausibleVoucherCode(normalised) {
  return /^[A-Z0-9]{8,24}$/.test(normalised);
}

module.exports = { VOUCHER_ALPHABET, VOUCHER_CODE_LENGTH, generateVoucherCode, normalizeVoucherCode, formatVoucherCode, isPlausibleVoucherCode };
